public class IstGeradeTest {

    public static boolean istGerade(int zahl) {
        return zahl % 2 == 0;
    }

    public static void pruefe(String name, boolean bedingung) {
        System.out.println((bedingung ? "OK   " : "FAIL ") + name);
    }

    public static void main(String[] args) {
        pruefe("gerade 4", istGerade(4) == true);
        pruefe("ungerade 7", istGerade(7) == false);
        pruefe("null ist gerade", istGerade(0) == true);
    }
}
